  DMAFAIL_DBGWRAP_MAP_OFFSET = 0x40000ULL,
  DMAFAIL_DMA_CTRL_MAP_OFFSET = 0x140000ULL,
  DMAFAIL_DMA_DATA_MAP_OFFSET = 0x150000ULL,
